sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below

    var assgn_to = g_form.getValue('assigned_to');
    var state1 = g_form.getValue('state');
    var bulk_tt = g_scratchpad.blkTskRelated;
    var unique = g_form.getUniqueValue();
    var host = g_scratchpad.host;
    var nam = g_scratchpad.name;
    var time1 = g_scratchpad.time;
    var user_access = g_scratchpad.usr_access;
    var user_was_maker = g_scratchpad.hasWorkedAsMaker; //MSSCUSTODY-5250

    g_form.setDisplay('lock', false);
    g_form.setDisplay('locktime', false);
    g_form.setDisplay('bulk_task_type', false);
    g_form.setDisplay('active_trade_count', false); //MSSCUSTODY-4282 Hiding the active_trade_count field.

    //MSSCUSTODY-5250 - If User does not belong to Assignment Group
    if ((bulk_tt == 'Maker' || bulk_tt == 'Checker') && (!user_access)) {
        makeFormReadOnly();
        return;
    }

    //MSSCUSTODY-5250 - If User has already worked as maker
    if ((bulk_tt == 'Checker') && (user_access) && (user_was_maker)) {
        makeFormReadOnly();
        alert('Checker cannot be the same user who actioned as a maker');
        return;
    }

    // Alert a user - If assign to is not empty or not the logged in user 
    if (assgn_to != "" && assgn_to != g_user.userID && (state1 == '2' || state1 == '1') && (bulk_tt == 'Maker') && (user_access)) {
        var ans = confirm("You are viewing a record which is already assigned to " + nam + ". Do you still want to work on it?");

		if (!ans) {
            setTimeout(makeFormReadOnly, 100); //MSSCUSTODY-5250 - If User clicks on Cancel
        } else {
            g_form.setValue('assigned_to', g_user.userID);
            g_form.setValue('locktime', time1);

            g_form.setMandatory('outcome', false);
            g_form.setMandatory('reason_code', false);
            g_form.setMandatory('suspend', false);
            g_form.setMandatory('cancel_by', false);
            g_form.setMandatory('settlement_type', false);

            g_form.save();

            g_form.setMandatory('outcome', true);
            g_form.setMandatory('reason_code', true);
            g_form.setMandatory('suspend', true);
            g_form.setMandatory('cancel_by', true);
            g_form.setMandatory('settlement_type', true);

            var new_assign = g_form.getValue('assigned_to');

            var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils'); //Scriptinclude
            ga.addParam('sysparm_name', 'updateTaskAssignmentClient'); //Method
            ga.addParam('userId', new_assign);
            ga.addParam('bulk_id', unique); //Parameters
            ga.getXMLAnswer(getResponse);

            function getResponse(response) {
                var g = response;
            }
        }
    } else {
        // do nothing
    }

    if (assgn_to != "" && assgn_to != g_user.userID && (state1 == '2' || state1 == '1') && (bulk_tt == 'Checker') && (user_access)) {
        var ans1 = confirm("You are viewing a record which is already assigned to " + nam + ". Do you still want to work on it?");

		if (!ans1) {
            setTimeout(makeFormReadOnly, 100); //MSSCUSTODY-5250 - If User clicks on Cancel
        } else {
            g_form.setValue('assigned_to', g_user.userID);
            g_form.setValue('locktime', time1);

            g_form.setMandatory('outcome', false);

            g_form.save();

            g_form.setMandatory('outcome', true);

            var new_assign1 = g_form.getValue('assigned_to');

            var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils'); //Scriptinclude
            ga1.addParam('sysparm_name', 'updateTaskAssignmentClient'); //Method
            ga1.addParam('userId', new_assign1);
            ga1.addParam('bulk_id', unique); //Parameters
            ga1.getXMLAnswer(getResponse);

            function getResponse(response) {
                var g1 = response;
            }
        }	
    } else {
        //do nothing
    }
}

// Function to make form read-only
function makeFormReadOnly() {
    var fields = g_form.getEditableFields();
	for (var i = 0; i < fields.length; i++) {
        var fieldName = fields[i];
        if (g_form.isMandatory(fieldName)) {
            g_form.setMandatory(fieldName, false); // Make non-mandatory if it is mandatory
        }
        g_form.setReadOnly(fieldName, true); // Set the field to read-only
    }
}
